CREATE TABLE "products" (
  "product_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_name" varchar NOT NULL,
  "product_code" varchar UNIQUE NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "product_environments" (
  "environment_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "environment_code" varchar NOT NULL,
  "environment_name" varchar NOT NULL,
  "created_at" timestamptz
);

CREATE TABLE "product_api_keys" (
  "key_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "environment_id" int,
  "key_name" varchar,
  "key_prefix" varchar NOT NULL,
  "key_hash" varchar NOT NULL,
  "permissions" jsonb NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "last_used_at" timestamptz,
  "expires_at" timestamptz,
  "revoked_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "projects" (
  "project_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "project_code" varchar NOT NULL,
  "project_name" varchar NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "project_features" (
  "category_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "project_id" int NOT NULL,
  "parent_id" int,
  "category_type" varchar,
  "category_code" varchar NOT NULL,
  "category_name" varchar NOT NULL,
  "full_path" varchar,
  "path_ids" varchar,
  "level" int NOT NULL DEFAULT 1,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "users" (
  "user_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar,
  "first_name" varchar,
  "last_name" varchar,
  "email" varchar UNIQUE NOT NULL,
  "phone_number" varchar,
  "password_hash" varchar,
  "is_active" boolean NOT NULL DEFAULT true,
  "last_login_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz,
  "deleted_at" timestamptz
);

CREATE TABLE "role_templates" (
  "template_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_code" varchar UNIQUE NOT NULL,
  "role_name" varchar NOT NULL,
  "description" text,
  "is_system_template" boolean NOT NULL DEFAULT false,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "platform_roles" (
  "platform_role_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_code" varchar UNIQUE NOT NULL,
  "role_name" varchar NOT NULL,
  "description" text,
  "permissions" jsonb NOT NULL,
  "is_system_role" boolean NOT NULL DEFAULT false,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "platform_memberships" (
  "platform_membership_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "platform_role_id" int NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "expires_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "product_roles" (
  "role_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "template_id" int,
  "role_code" varchar NOT NULL,
  "role_name" varchar NOT NULL,
  "permissions" jsonb NOT NULL,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "product_memberships" (
  "membership_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "product_id" int NOT NULL,
  "role_id" int NOT NULL,
  "expires_at" timestamptz,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "product_membership_scopes" (
  "scope_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "membership_id" int NOT NULL,
  "product_id" int NOT NULL,
  "project_id" int,
  "category_id" int,
  "scope_level" varchar NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "user_role_permission_rules" (
  "permission_rule_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "product_id" int,
  "role_id" int,
  "project_id" int,
  "category_id" int,
  "resource_type" varchar NOT NULL,
  "action" varchar NOT NULL,
  "effect" varchar NOT NULL,
  "scope_level" varchar NOT NULL,
  "granted_by" int,
  "is_active" boolean NOT NULL DEFAULT true,
  "expires_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_sources" (
  "source_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int,
  "source_code" varchar NOT NULL,
  "source_name" varchar NOT NULL,
  "source_type" varchar NOT NULL DEFAULT 'UNKNOWN',
  "source_platform" varchar NOT NULL DEFAULT 'UNKNOWN',
  "runtime_name" varchar,
  "sdk_name" varchar,
  "sdk_version" varchar,
  "discovery_status" varchar NOT NULL DEFAULT 'AUTO_DISCOVERED',
  "created_by_source" varchar NOT NULL DEFAULT 'SYSTEM',
  "first_seen_at" timestamptz,
  "last_seen_at" timestamptz,
  "description" text,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_ingestion_policies" (
  "policy_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "environment_id" int NOT NULL,
  "max_logs_per_minute" int,
  "max_batch_size" int,
  "flush_interval_seconds" int,
  "max_retries" int,
  "retry_interval_seconds" int,
  "queue_enabled" boolean NOT NULL DEFAULT true,
  "queue_worker_enabled" boolean NOT NULL DEFAULT true,
  "queue_lock_timeout_seconds" int NOT NULL DEFAULT 600,
  "strict_ordering_enabled" boolean NOT NULL DEFAULT true,
  "retention_days" int,
  "archive_enabled" boolean NOT NULL DEFAULT false,
  "archive_format" varchar,
  "archive_storage_path" text,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_masking_rules" (
  "masking_rule_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int,
  "field_key" varchar,
  "field_path" varchar,
  "match_type" varchar,
  "mask_type" varchar,
  "mask_value" varchar,
  "secret_handling_mode" varchar NOT NULL DEFAULT 'MASK_ONLY',
  "encryption_required" boolean NOT NULL DEFAULT false,
  "view_requires_password" boolean NOT NULL DEFAULT false,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_field_definitions" (
  "field_definition_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int,
  "project_id" int,
  "category_id" int,
  "field_key" varchar NOT NULL,
  "display_name" varchar,
  "description" text,
  "source_section" varchar NOT NULL,
  "field_path" varchar,
  "elastic_field_name" varchar NOT NULL,
  "data_type" varchar NOT NULL,
  "value_source_type" varchar NOT NULL DEFAULT 'NONE',
  "value_source_key" varchar,
  "is_required" boolean NOT NULL DEFAULT false,
  "is_sensitive" boolean NOT NULL DEFAULT false,
  "mask_before_index" boolean NOT NULL DEFAULT false,
  "encrypt_before_archive" boolean NOT NULL DEFAULT false,
  "is_visible" boolean NOT NULL DEFAULT true,
  "is_searchable" boolean NOT NULL DEFAULT false,
  "is_filterable" boolean NOT NULL DEFAULT false,
  "is_sortable" boolean NOT NULL DEFAULT false,
  "is_aggregatable" boolean NOT NULL DEFAULT false,
  "display_order" int,
  "default_value" text,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_field_enum_options" (
  "option_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "field_definition_id" int NOT NULL,
  "option_key" varchar NOT NULL,
  "option_label" varchar NOT NULL,
  "option_value" varchar NOT NULL,
  "display_order" int,
  "is_default" boolean NOT NULL DEFAULT false,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_field_value_sources" (
  "value_source_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "field_definition_id" int NOT NULL,
  "source_type" varchar NOT NULL,
  "source_key" varchar NOT NULL,
  "source_config" jsonb,
  "label_field" varchar,
  "value_field" varchar,
  "is_required" boolean NOT NULL DEFAULT false,
  "timeout_seconds" int,
  "refresh_mode" varchar NOT NULL DEFAULT 'ON_DEMAND',
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_queue_batches" (
  "batch_id" uuid PRIMARY KEY,
  "product_id" int,
  "source_id" int,
  "environment_id" int,
  "queue_key" varchar NOT NULL,
  "source_type" varchar NOT NULL DEFAULT 'UNKNOWN',
  "source_platform" varchar NOT NULL DEFAULT 'UNKNOWN',
  "source_ip" varchar,
  "user_agent" text,
  "idempotency_key" varchar,
  "detected_product_code" varchar,
  "product_resolution_status" varchar NOT NULL DEFAULT 'RESOLVED',
  "product_resolution_reason" text,
  "product_resolved_at" timestamptz,
  "available_at" timestamptz,
  "worker_id" varchar,
  "processing_attempts" int NOT NULL DEFAULT 0,
  "total_logs" int NOT NULL DEFAULT 0,
  "status" varchar NOT NULL DEFAULT 'QUEUED',
  "priority" int NOT NULL DEFAULT 0,
  "received_at" timestamptz,
  "processing_started_at" timestamptz,
  "processed_at" timestamptz,
  "retention_until" timestamptz,
  "purged_at" timestamptz,
  "locked_by" varchar,
  "locked_at" timestamptz,
  "error_message" text,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_queue_items" (
  "queue_item_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "batch_id" uuid NOT NULL,
  "sequence_no" int NOT NULL,
  "source_type" varchar NOT NULL DEFAULT 'UNKNOWN',
  "source_platform" varchar NOT NULL DEFAULT 'UNKNOWN',
  "input_payload" jsonb,
  "payload_size_bytes" bigint,
  "payload_purged" boolean NOT NULL DEFAULT false,
  "detected_product_code" varchar,
  "worker_id" varchar,
  "processing_attempts" int NOT NULL DEFAULT 0,
  "status" varchar NOT NULL DEFAULT 'PENDING',
  "retry_count" int NOT NULL DEFAULT 0,
  "max_retry_count" int NOT NULL DEFAULT 3,
  "next_retry_at" timestamptz,
  "last_retry_at" timestamptz,
  "processing_started_at" timestamptz,
  "processed_at" timestamptz,
  "error_message" text,
  "retention_until" timestamptz,
  "purged_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_failures" (
  "failure_id" uuid PRIMARY KEY,
  "attempt_no" int NOT NULL DEFAULT 1,
  "queue_item_id" bigint NOT NULL,
  "batch_id" uuid NOT NULL,
  "product_id" int,
  "source_id" int,
  "environment_id" int,
  "failure_stage" varchar NOT NULL,
  "failure_type" varchar NOT NULL,
  "reason" text,
  "error_details" jsonb,
  "retry_count" int NOT NULL DEFAULT 0,
  "max_retry_count" int NOT NULL DEFAULT 3,
  "next_retry_at" timestamptz,
  "last_retry_at" timestamptz,
  "status" varchar NOT NULL DEFAULT 'FAILED',
  "created_at" timestamptz,
  "resolved_at" timestamptz
);

CREATE TABLE "system_audit_logs" (
  "audit_id" uuid PRIMARY KEY,
  "user_id" int,
  "product_id" int,
  "action" varchar NOT NULL,
  "method" varchar,
  "url" text,
  "ip_address" varchar,
  "query_json" jsonb,
  "payload" jsonb,
  "created_at" timestamptz
);

CREATE TABLE "sensitive_log_access_requests" (
  "request_id" uuid PRIMARY KEY,
  "user_id" int NOT NULL,
  "product_id" int NOT NULL,
  "log_id" uuid,
  "field_definition_id" int,
  "secret_id" uuid,
  "field_path" varchar,
  "reason" text,
  "approval_status" varchar NOT NULL,
  "approved_by" int,
  "approved_at" timestamptz,
  "expires_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_sensitive_field_secrets" (
  "secret_id" uuid PRIMARY KEY,
  "log_id" uuid NOT NULL,
  "product_id" int NOT NULL,
  "project_id" int,
  "category_id" int,
  "environment_id" int,
  "field_definition_id" int,
  "field_key" varchar NOT NULL,
  "field_path" varchar NOT NULL,
  "source_section" varchar NOT NULL,
  "value_hash" varchar,
  "encrypted_value" text NOT NULL,
  "encryption_key_ref" varchar,
  "encryption_algorithm" varchar,
  "requires_approval" boolean NOT NULL DEFAULT true,
  "retention_until" timestamptz,
  "purged_at" timestamptz,
  "created_at" timestamptz
);

CREATE TABLE "sensitive_log_access_history" (
  "access_id" uuid PRIMARY KEY,
  "request_id" uuid,
  "product_id" int,
  "user_id" int NOT NULL,
  "project_id" int,
  "category_id" int,
  "log_id" uuid,
  "field_path" varchar,
  "access_reason" text,
  "auth_method" varchar,
  "access_status" varchar,
  "created_at" timestamptz
);

CREATE TABLE "log_archives" (
  "archive_id" uuid PRIMARY KEY,
  "product_id" int NOT NULL,
  "environment_id" int,
  "project_id" int,
  "archive_year" int NOT NULL,
  "archive_month" int NOT NULL,
  "date_from" timestamptz,
  "date_to" timestamptz,
  "storage_provider" varchar NOT NULL DEFAULT 'GCS',
  "bucket_name" varchar,
  "file_path" text,
  "file_format" varchar,
  "total_logs" int,
  "compressed_size_bytes" bigint,
  "checksum" varchar,
  "status" varchar,
  "exported_at" timestamptz,
  "restored_at" timestamptz,
  "purged_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "elastic_index_policies" (
  "elastic_policy_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "product_id" int NOT NULL,
  "environment_id" int,
  "index_prefix" varchar NOT NULL,
  "index_pattern" varchar,
  "write_alias" varchar,
  "rollover_type" varchar NOT NULL DEFAULT 'MONTHLY',
  "number_of_shards" int NOT NULL DEFAULT 1,
  "number_of_replicas" int NOT NULL DEFAULT 1,
  "retention_days" int,
  "schema_version" varchar NOT NULL DEFAULT 'v1',
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_index_refs" (
  "log_id" uuid PRIMARY KEY,
  "product_id" int NOT NULL,
  "project_id" int,
  "category_id" int,
  "environment_id" int NOT NULL,
  "source_id" int,
  "batch_id" uuid,
  "queue_item_id" bigint,
  "response_status_code" int,
  "duration_ms" int,
  "log_level" varchar,
  "event_type" varchar,
  "source_request_id" varchar,
  "correlation_id" varchar,
  "trace_id" varchar,
  "span_id" varchar,
  "parent_span_id" varchar,
  "request_method" varchar,
  "request_path" text,
  "route_pattern" text,
  "feature_full_path" text,
  "feature_path_ids" varchar,
  "timestamp" timestamptz NOT NULL,
  "ingested_at" timestamptz,
  "elastic_index" varchar NOT NULL,
  "elastic_document_id" varchar NOT NULL,
  "index_status" varchar NOT NULL DEFAULT 'PENDING',
  "indexed_at" timestamptz,
  "last_sync_at" timestamptz,
  "sync_error" text,
  "is_archived" boolean NOT NULL DEFAULT false,
  "archived_at" timestamptz,
  "deleted_at" timestamptz,
  "created_at" timestamptz,
  "updated_at" timestamptz
);

CREATE TABLE "log_object_storage_refs" (
  "object_ref_id" uuid PRIMARY KEY,
  "log_id" uuid NOT NULL,
  "product_id" int NOT NULL,
  "environment_id" int,
  "storage_provider" varchar NOT NULL DEFAULT 'GCS',
  "bucket_name" varchar,
  "object_path" text NOT NULL,
  "object_type" varchar NOT NULL,
  "file_format" varchar,
  "size_bytes" bigint,
  "checksum" varchar,
  "is_encrypted" boolean NOT NULL DEFAULT false,
  "retention_until" timestamptz,
  "purged_at" timestamptz,
  "created_at" timestamptz
);

